#!/usr/bin/env python3
"""drug/pubchem_chembl_lookup — auto-generated run.py (archetype=drug).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "drug"
BRAIN = "drug"
SKILL = "pubchem_chembl_lookup"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'pubchem_chembl_lookup', 'n_compounds': 0, 'best_score': 0.0, 'compound_csv': '', 'diagnostics': {'brain': 'drug', 'archetype': 'drug'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """PubChem + ChEMBL REST lookup(用 requests,不依赖 pubchempy)。
    输入:cids / smiles / inchi_key / chembl_ids / search_type (default 'smiles')
    输出:results (list of {cid, smiles, mw, name, chembl_id, targets[]})
    """
    import os as _os
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    queries = payload.get("smiles_list") or payload.get("cids") or []
    search_type = payload.get("search_type", "smiles")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "n_queries": len(queries), "search_type": search_type}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "results": [],
                "diagnostics": {**diagnostics, "dry": True}}
    if not queries:
        return {"ok": False, "error": "需要 smiles_list 或 cids", "diagnostics": diagnostics}

    script = (
        "import json, sys, urllib.parse, urllib.request\n"
        f"queries = {queries!r}; search_type = {search_type!r}\n"
        "BASE = 'https://pubchem.ncbi.nlm.nih.gov/rest/pug'\n"
        "results = []\n"
        "for q in queries:\n"
        "    try:\n"
        "        qenc = urllib.parse.quote(str(q), safe='')\n"
        "        url = f'{BASE}/compound/{search_type}/{qenc}/property/MolecularFormula,MolecularWeight,CanonicalSMILES,IUPACName/JSON'\n"
        "        with urllib.request.urlopen(url, timeout=20) as resp:\n"
        "            data = json.loads(resp.read().decode('utf-8'))\n"
        "        props = data.get('PropertyTable', {}).get('Properties', [])\n"
        "        if not props: results.append({'query': q, 'found': False}); continue\n"
        "        p = props[0]\n"
        "        results.append({'query': q, 'found': True,\n"
        "                        'cid': p.get('CID'),\n"
        "                        'smiles': p.get('CanonicalSMILES'),\n"
        "                        'mw': p.get('MolecularWeight'),\n"
        "                        'name': p.get('IUPACName'),\n"
        "                        'formula': p.get('MolecularFormula')})\n"
        "    except Exception as e:\n"
        "        results.append({'query': q, 'found': False, 'error': repr(e)[:120]})\n"
        "json.dump({'results': results, 'n_found': sum(1 for r in results if r.get('found'))}, sys.stdout)\n"
    )
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 120)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "lookup 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed, "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
